        "com.google.android.apps.wellbeing"          = "Dijital Denge (Digital Wellbeing)"
        "com.samsung.android.forest"                 = "Samsung Dijital Denge"
        "com.sec.android.app.samsungapps"            = "Samsung Galaxy Store"
        "com.samsung.android.samsungpass"            = "Samsung Pass (Sifre Yoneticisi)"
