# ------------------------------------------------------------------------------
# 5. Yedekleme (Snapshot) ve Geri Yukleme (Restore) Motoru
# ------------------------------------------------------------------------------

function Get-AndroidSettingValue {
    param(
        [string]$Namespace,
        [string]$Key
    )
    $out = Invoke-Adb -Arguments @("shell", "settings", "get", $Namespace, $Key)
    if ($script:LastAdbExitCode -ne 0) { return "__ERROR__" }
    $val = ($out -join "").Trim()
    if (-not $val -or $val -eq "null") { return "null" }
    return $val
}

function Save-DeviceBackup {
    param(
        [string]$Reason,
        [object[]]$PackageRecords = @(),
        [object[]]$SettingRecords = @()
    )

    if (-not $script:BackupDir) { return $null }

    $prefix = Get-DeviceFilePrefix
    $stamp = Get-Date -Format "yyyyMMdd_HHmmss"
    $filePath = Join-Path $script:BackupDir "${prefix}_${stamp}_backup.json"

    $payload = [PSCustomObject]@{
        Version   = $script:Version
        Timestamp = (Get-Date -Format "yyyy-MM-dd HH:mm:ss")
        Reason    = $Reason
        Device    = $script:DeviceInfo
        Packages  = @($PackageRecords)
        Settings  = @($SettingRecords)
    }

    try {
        $json = $payload | ConvertTo-Json -Depth 6
        [System.IO.File]::WriteAllText($filePath, $json, [System.Text.Encoding]::UTF8)
        Write-Host "  [YEDEK] Kaydedildi: $(Split-Path $filePath -Leaf)" -ForegroundColor DarkCyan
        Write-Log "Yedek kaydedildi: $filePath ($Reason | Paket: $($PackageRecords.Count), Ayar: $($SettingRecords.Count))"
        return $filePath
    } catch {
        Write-Host "  [UYARI] Yedek kaydedilemedi: $($_.Exception.Message)" -ForegroundColor Yellow
        Write-Log "Yedek hatasi: $($_.Exception.Message)" "WARN"
        return $null
    }
}

function Restore-DeviceBackup {
    param([string]$BackupFilePath)

    if (-not (Assert-DeviceConnected)) { return }

    if (-not $BackupFilePath) {
        $files = @(Get-ChildItem -Path $script:BackupDir -Filter "*_backup.json" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending)
        if ($files.Count -eq 0) {
            Write-Host ""
            Write-Host "[i] Hic yedek dosyasi bulunamadi ($($script:BackupDir))." -ForegroundColor Yellow
            return
        }

        $currentPrefix = Get-DeviceFilePrefix
        Write-Host ""
        Write-Host "=== Yedekten Geri Yukleme (Restore) ===" -ForegroundColor Cyan
        for ($i = 0; $i -lt $files.Count; $i++) {
            $f = $files[$i]
            $tag = if ($f.Name.StartsWith($currentPrefix)) { "[BU CIHAZ] " } else { "" }
            Write-Host ("  [{0}] {1}{2}" -f ($i + 1), $tag, $f.Name) -ForegroundColor $(if ($tag) { "Green" } else { "Gray" })
        }
        Write-Host "  [0] Iptal"
        $sel = Read-Host "Geri yuklenecek yedegi secin"
        $idx = 0
        if ($sel -eq "0" -or -not [int]::TryParse($sel, [ref]$idx) -or $idx -lt 1 -or $idx -gt $files.Count) {
            return
        }
        $BackupFilePath = $files[$idx - 1].FullName
    }

    if (-not (Test-Path $BackupFilePath)) {
        Write-Host "[HATA] Yedek dosyasi bulunamadi: $BackupFilePath" -ForegroundColor Red
        return
    }

    try {
        $data = Get-Content -Path $BackupFilePath -Raw -Encoding UTF8 | ConvertFrom-Json
    } catch {
        Write-Host "[HATA] Yedek dosyasi okunamadi: $($_.Exception.Message)" -ForegroundColor Red
        return
    }

    $pkgList = @($data.Packages)
    $setList = @($data.Settings)

    Write-Host ""
    Write-Host "Yedek Bilgisi: $($data.Reason) | Tarih: $($data.Timestamp)" -ForegroundColor Cyan
    Write-Host "  Paket kaydi: $($pkgList.Count) | Sistem ayari kaydi: $($setList.Count)" -ForegroundColor Gray

    $mode = "3"
    if (-not $NonInteractive) {
        Write-Host "  [1] Sadece Paketleri Geri Yukle"
        Write-Host "  [2] Sadece Sistem Ayarlarini Geri Yukle"
        Write-Host "  [3] Hepsini Geri Yukle (Paketler + Ayarlar)"
        Write-Host "  [0] Iptal"
        $mode = Read-Host "Seciminiz"
        if ($mode -eq "0" -or $mode -notin @("1", "2", "3")) { return }
    }

    if (($mode -eq "1" -or $mode -eq "3") -and $pkgList.Count -gt 0) {
        Write-Host ""
        Write-Host "Paketler geri yukleniyor..." -ForegroundColor Cyan
        $okCount = 0; $errCount = 0
        foreach ($p in $pkgList) {
            $pkg = $p.Pkg
            if ($p.AppliedAction -eq "uninstall") {
                $out = Invoke-Adb -Arguments @("shell", "cmd", "package", "install-existing", "--user", "0", $pkg)
                $txt = ($out -join " ").Trim()
                if ($txt -notmatch "installed for user") {
                    $out = Invoke-Adb -Arguments @("shell", "cmd", "package", "install-existing", $pkg)
                    $txt = ($out -join " ").Trim()
                }
                if ($txt -match "installed for user") {
                    Write-Host "  [GERI YUKLENDI] $pkg" -ForegroundColor Green
                    Write-Log "Geri yuklendi (install-existing): $pkg"
                    $okCount++
                } else {
                    Write-Host "  [HATA]          $pkg -> $txt" -ForegroundColor Red
                    Write-Log "Geri yukleme hatasi ($pkg): $txt" "ERROR"
                    $errCount++
                }
            } elseif ($p.AppliedAction -eq "disable") {
                $out = Invoke-Adb -Arguments @("shell", "pm", "enable", "--user", "0", $pkg)
                $txt = ($out -join " ").Trim()
                if ($txt -notmatch "enabled") {
                    $out = Invoke-Adb -Arguments @("shell", "pm", "enable", $pkg)
                    $txt = ($out -join " ").Trim()
                }
                if ($txt -match "enabled") {
                    Write-Host "  [ETKINLESTIRILDI] $pkg" -ForegroundColor Green
                    Write-Log "Etkinlestirildi (pm enable): $pkg"
                    $okCount++
                } else {
                    Write-Host "  [HATA]            $pkg -> $txt" -ForegroundColor Red
                    Write-Log "Etkinlestirme hatasi ($pkg): $txt" "ERROR"
                    $errCount++
                }
            }
        }
        Write-Host "Paket geri yukleme ozeti -> Basarili: $okCount | Hata: $errCount" -ForegroundColor White
        [void](Get-DevicePackageState)
    }

    if (($mode -eq "2" -or $mode -eq "3") -and $setList.Count -gt 0) {
        Write-Host ""
        Write-Host "Sistem ayarlari orijinal degerlerine donduruluyor..." -ForegroundColor Cyan
        foreach ($s in $setList) {
            if ($s.OldValue -eq "__ERROR__") { continue }
            if ($s.OldValue -eq "null" -or [string]::IsNullOrEmpty($s.OldValue)) {
                $out = Invoke-Adb -Arguments @("shell", "settings", "delete", $s.Namespace, $s.Key)
                Write-Host "  [SILINDI/VARSAYILAN] $($s.Namespace)/$($s.Key)" -ForegroundColor Green
                Write-Log "Ayar silindi (varsayilan): $($s.Namespace)/$($s.Key)"
            } else {
                Set-AndroidSetting -Namespace $s.Namespace -Key $s.Key -Value $s.OldValue -SilentBackup
            }
        }
        Write-Host "Sistem ayarlari geri yuklendi." -ForegroundColor Green
    }
}

# ------------------------------------------------------------------------------
# 6. Paket Eslestirme, Onizleme, Debloat Motoru ve Manuel Paket Yoneticisi
# ------------------------------------------------------------------------------

function Get-MatchingItems {
    param(
        [object[]]$Catalog,
        [int]$MaxTier,
        [switch]$IncludeWhitelisted
    )

    $matched = New-Object 'System.Collections.Generic.List[object]'
    foreach ($item in $Catalog) {
        if ($item.Tier -gt $MaxTier) { continue }
        if (-not $IncludeWhitelisted -and $script:Whitelist.Contains($item.Pkg)) { continue }

        if ($item.Action -eq "uninstall") {
            if ($script:InstalledPackages.Contains($item.Pkg)) {
                $matched.Add($item)
            }
        } elseif ($item.Action -eq "disable") {
            if ($script:EnabledPackages.Contains($item.Pkg)) {
                $matched.Add($item)
            }
        }
    }
    return $matched.ToArray()
}

function Invoke-DebloatItems {
    param(
        [object[]]$Targets,
        [string]$ReasonLabel
    )

    if (-not (Assert-DeviceConnected)) { return }

    if (-not $Targets -or $Targets.Count -eq 0) {
        Write-Host ""
        Write-Host "[i] Islem yapilacak paket bulunamadi." -ForegroundColor Yellow
        return
    }

    $beforeMetrics = Get-DeviceMetrics
    $beforePkgCount = $script:InstalledPackages.Count

    Write-Host ""
    Write-Host "$ReasonLabel baslatiliyor ($($Targets.Count) paket)..." -ForegroundColor Cyan
    Write-Log "Debloat basladi: $ReasonLabel ($($Targets.Count) paket)"

    $removedCount = 0
    $disabledCount = 0
    $errorCount = 0
    $backupRecords = New-Object 'System.Collections.Generic.List[object]'

    foreach ($item in $Targets) {
        $pkg = $item.Pkg
        if ($item.Action -eq "uninstall") {
            $out = Invoke-Adb -Arguments @("shell", "pm", "uninstall", "--user", "0", $pkg)
            $text = ($out -join " ").Trim()
            if ($text -match "Success") {
                Write-Host "  [KALDIRILDI]  $pkg" -ForegroundColor Green
                Write-Log "Kaldirildi: $pkg"
                $backupRecords.Add([PSCustomObject]@{ Pkg = $pkg; AppliedAction = "uninstall"; Group = $item.Group })
                $removedCount++
            } else {
                # Otomatik fallback: uninstall basarisizsa disable-user dene
                [void](Invoke-Adb -Arguments @("shell", "am", "force-stop", $pkg))
                $fbOut = Invoke-Adb -Arguments @("shell", "pm", "disable-user", "--user", "0", $pkg)
                $fbText = ($fbOut -join " ").Trim()
                if ($fbText -match "disabled-user|new state: disabled") {
                    Write-Host "  [DEVRE DISI*] $pkg (uninstall yerine disable uygulandi)" -ForegroundColor Cyan
                    Write-Log "Fallback devre disi: $pkg (uninstall hatasi: $text)"
                    $backupRecords.Add([PSCustomObject]@{ Pkg = $pkg; AppliedAction = "disable"; Group = $item.Group })
                    $disabledCount++
                } else {
                    Write-Host "  [HATA]        $pkg -> $text" -ForegroundColor Red
                    Write-Log "Hata ($pkg): $text" "ERROR"
                    $errorCount++
                }
            }
        } else {
            [void](Invoke-Adb -Arguments @("shell", "am", "force-stop", $pkg))
            $out = Invoke-Adb -Arguments @("shell", "pm", "disable-user", "--user", "0", $pkg)
            $text = ($out -join " ").Trim()
            if ($text -match "disabled-user|new state: disabled") {
                Write-Host "  [DEVRE DISI]  $pkg" -ForegroundColor Cyan
                Write-Log "Devre disi: $pkg"
                $backupRecords.Add([PSCustomObject]@{ Pkg = $pkg; AppliedAction = "disable"; Group = $item.Group })
                $disabledCount++
            } else {
                Write-Host "  [HATA]        $pkg -> $text" -ForegroundColor Red
                Write-Log "Hata ($pkg): $text" "ERROR"
                $errorCount++
            }
        }
    }

    if ($backupRecords.Count -gt 0) {
        [void](Save-DeviceBackup -Reason $ReasonLabel -PackageRecords $backupRecords.ToArray())
    }

    Write-Host ""
    Write-Host "Ozet -> Kaldirilan: $removedCount | Devre Disi: $disabledCount | Hata: $errorCount" -ForegroundColor White
    Write-Host "Paket listesi guncelleniyor..." -ForegroundColor DarkGray
    [void](Get-DevicePackageState)
    $afterMetrics = Get-DeviceMetrics
    Write-Host ("Durum -> Kurulu Paket: {0} -> {1} | Bos Alan: {2} -> {3}" -f $beforePkgCount, $script:InstalledPackages.Count, $beforeMetrics.FreeSpace, $afterMetrics.FreeSpace) -ForegroundColor DarkCyan
}

function Invoke-DebloatTier {
    param(
        [object[]]$Catalog,
        [int]$MaxTier,
        [switch]$SkipConfirm
    )

    $targets = Get-MatchingItems -Catalog $Catalog -MaxTier $MaxTier
    if ($targets.Count -eq 0) {
        Write-Host ""
        Write-Host "[i] Seviye $MaxTier icin bu cihazda temizlenecek paket kalmamis." -ForegroundColor Yellow
        return
    }

    if (-not $SkipConfirm -and -not $NonInteractive) {
        Write-Host ""
        if ($MaxTier -eq 3) {
            Write-Host "[DIKKAT] Seviye 3; Google Drive, Android Auto, Galaxy Wearable, magaza ve bulut servisleri gibi kritik uygulamalari da icerir!" -ForegroundColor Red
        }
        $ans = Read-Host "Seviye $MaxTier kapsaminda $($targets.Count) paket uzerinde islem yapilacak. Onayliyor musunuz? (E/H)"
        if ($ans -notmatch "^[EeYy]$") {
            Write-Host "Islem iptal edildi." -ForegroundColor Yellow
            return
        }
    }

    Invoke-DebloatItems -Targets $targets -ReasonLabel "Seviye $MaxTier Debloat"
}

function Invoke-InteractiveGridDebloat {
    param([object[]]$Catalog)

    $allMatched = Get-MatchingItems -Catalog $Catalog -MaxTier 3
    if ($allMatched.Count -eq 0) {
        Write-Host "[i] Cihazda katalogla eslesen paket bulunamadi." -ForegroundColor Yellow
        return
    }

    if (-not (Get-Command Out-GridView -ErrorAction SilentlyContinue)) {
        Write-Host "[UYARI] Bu PowerShell ortaminda Out-GridView desteklenmiyor." -ForegroundColor Yellow
        return
    }

    Write-Host ""
    Write-Host "Gorsel secim penceresi aciliyor... (Ctrl/Shift ile coklu secim yapip Tamam'a basin)" -ForegroundColor Cyan
    $selected = $allMatched |
        Select-Object Tier, Action, Pkg, Desc, Group |
        Out-GridView -Title "Android Universal Debloat - Kaldirilacak / Devre Disi Birakilacak Paketleri Secin" -PassThru

    if (-not $selected) {
        Write-Host "Hicbir paket secilmedi." -ForegroundColor Yellow
        return
    }

    $selectedArr = @($selected)
    $ans = Read-Host "Secilen $($selectedArr.Count) paket isleme alinsin mi? (E/H)"
    if ($ans -match "^[EeYy]$") {
        Invoke-DebloatItems -Targets $selectedArr -ReasonLabel "Secmeli (GridView) Debloat"
    }
}

function Invoke-ManualPackageManager {
    if (-not (Assert-DeviceConnected)) { return }

    while ($true) {
        Write-Host ""
        Write-Host "=== Manuel Paket Yoneticisi & Whitelist ===" -ForegroundColor Cyan
        Write-Host "  [1] Cihazda kurulu paketlerde ara & islem yap (Kaldir/Devre Disi)"
        Write-Host "  [2] Tekil paket geri yukle / etkinlestir (Paket adi gir)"
        Write-Host "  [3] Whitelist (Haric Tutma) listesini goruntule / duzenle"
        Write-Host "  [0] Ana Menuye Don"
        $sub = Read-Host "Seciminiz"

        if ($sub -eq "0") { return }

        if ($sub -eq "1") {
            $q = Read-Host "Aranacak kelime (orn. facebook, samsung, google, miui)"
            if (-not $q) { continue }
            $hits = @($script:InstalledPackages | Where-Object { $_ -like "*$q*" } | Sort-Object)
            if ($hits.Count -eq 0) {
                Write-Host "Eslesen paket bulunamadi." -ForegroundColor Yellow
                continue
            }
            for ($i = 0; $i -lt $hits.Count; $i++) {
                $st = if ($script:EnabledPackages.Contains($hits[$i])) { "[aktif]" } else { "[devre disi]" }
                Write-Host ("  [{0}] {1} {2}" -f ($i + 1), $hits[$i], $st)
            }
            $sel = Read-Host "Islem yapilacak numara (Iptal icin 0)"
            $idx = 0
            if (-not [int]::TryParse($sel, [ref]$idx) -or $idx -lt 1 -or $idx -gt $hits.Count) { continue }
            $targetPkg = $hits[$idx - 1]
            $act = Read-Host "Islem secin: [U] Kaldir (uninstall) | [D] Devre disi (disable) | [E] Etkinlestir (enable) | [W] Whitelist'e ekle"
            if ($act -match "^[Uu]$") {
                Invoke-DebloatItems -Targets @([PSCustomObject]@{ Pkg = $targetPkg; Action = "uninstall"; Group = "Manuel" }) -ReasonLabel "Manuel Kaldirma"
            } elseif ($act -match "^[Dd]$") {
                Invoke-DebloatItems -Targets @([PSCustomObject]@{ Pkg = $targetPkg; Action = "disable"; Group = "Manuel" }) -ReasonLabel "Manuel Devre Disi"
            } elseif ($act -match "^[Ee]$") {
                $out = Invoke-Adb -Arguments @("shell", "pm", "enable", "--user", "0", $targetPkg)
                Write-Host ($out -join " ") -ForegroundColor Green
                [void](Get-DevicePackageState)
            } elseif ($act -match "^[Ww]$") {
                Add-Content -Path $script:WhitelistPath -Value $targetPkg
                Read-Whitelist
                Write-Host "[OK] Whitelist'e eklendi: $targetPkg" -ForegroundColor Green
            }
        } elseif ($sub -eq "2") {
            $pkg = Read-Host "Geri yuklenecek/etkinlestirilecek tam paket adi (orn. com.google.android.apps.docs)"
            if (-not $pkg) { continue }
            $out1 = Invoke-Adb -Arguments @("shell", "cmd", "package", "install-existing", "--user", "0", $pkg)
            $out2 = Invoke-Adb -Arguments @("shell", "pm", "enable", "--user", "0", $pkg)
            Write-Host "  install-existing: $($out1 -join ' ')" -ForegroundColor Cyan
            Write-Host "  pm enable       : $($out2 -join ' ')" -ForegroundColor Cyan
            Write-Log "Manuel geri yukleme ($pkg): $($out1 -join ' ') | $($out2 -join ' ')"
            [void](Get-DevicePackageState)
        } elseif ($sub -eq "3") {
            Read-Whitelist
            Write-Host ""
            Write-Host "Whitelist dosyasi: $($script:WhitelistPath)" -ForegroundColor Gray
            if ($script:Whitelist.Count -eq 0) {
                Write-Host "  (Su an haric tutulan paket yok)" -ForegroundColor DarkGray
            } else {
                foreach ($w in ($script:Whitelist | Sort-Object)) {
                    Write-Host "  - $w" -ForegroundColor Green
                }
            }
            $wlAct = Read-Host "[E] Paket ekle | [S] Paket sil | [Enter] Geri"
            if ($wlAct -match "^[Ee]$") {
                $newPkg = Read-Host "Eklenecek paket adi"
                if ($newPkg) {
                    Add-Content -Path $script:WhitelistPath -Value $newPkg.Trim()
                    Read-Whitelist
                    Write-Host "[OK] Eklendi." -ForegroundColor Green
                }
            } elseif ($wlAct -match "^[Ss]$") {
                $delPkg = Read-Host "Silinecek paket adi"
                if ($delPkg) {
                    $lines = Get-Content -Path $script:WhitelistPath | Where-Object { $_.Trim() -ne $delPkg.Trim() }
                    Set-Content -Path $script:WhitelistPath -Value $lines
                    Read-Whitelist
                    Write-Host "[OK] Cikarildi." -ForegroundColor Green
                }
            }
        }
    }
}

function Show-DryRunPreview {
    param([object[]]$Catalog)

    Write-Host ""
    Write-Host "=== ONIZLEME (DRY-RUN) - Cihazda Eslesen Paketler ===" -ForegroundColor Cyan

    $anyFound = $false
    foreach ($tier in @(1, 2, 3)) {
        $tierLabel = switch ($tier) {
            1 { "Seviye 1 - Guvenli" }
            2 { "Seviye 2 - Dengeli" }
            3 { "Seviye 3 - Agresif (Hard)" }
        }
        $items = @()
        foreach ($item in $Catalog) {
            if ($item.Tier -ne $tier) { continue }
            if (($item.Action -eq "uninstall" -and $script:InstalledPackages.Contains($item.Pkg)) -or
                ($item.Action -eq "disable" -and $script:EnabledPackages.Contains($item.Pkg))) {
                $items += $item
            }
        }

        Write-Host ""
        Write-Host "[$tierLabel] ($($items.Count) paket)" -ForegroundColor Yellow
        if ($items.Count -eq 0) {
            Write-Host "  (Eslesen paket yok)" -ForegroundColor DarkGray
            continue
        }
        $anyFound = $true
        $grouped = $items | Group-Object -Property Group
        foreach ($g in $grouped) {
            Write-Host "  * $($g.Name):" -ForegroundColor White
            foreach ($entry in $g.Group) {
                $tag = if ($entry.Action -eq "disable") { "[disable]" } else { "[uninstall]" }
                $wlTag = if ($script:Whitelist.Contains($entry.Pkg)) { " [WHITELIST - ATLANACAK]" } else { "" }
                $descText = if ($entry.Desc -and $entry.Desc -ne $entry.Group) { " - $($entry.Desc)" } else { "" }
                $color = if ($wlTag) { "DarkYellow" } else { "Gray" }
                Write-Host "      $tag $($entry.Pkg)$descText$wlTag" -ForegroundColor $color
            }
        }
    }

    if (-not $anyFound) {
        Write-Host ""
        Write-Host "[i] Cihaziniz zaten tamamen temiz gorunuyor." -ForegroundColor Green
    }
}

# ------------------------------------------------------------------------------
# 7. Sistem Ayar Optimizasyon Motoru & Secmeli Private DNS
# ------------------------------------------------------------------------------

function Set-AndroidSetting {
    param(
        [string]$Namespace,
        [string]$Key,
        [string]$Value,
        [System.Collections.Generic.List[object]]$BackupList,
        [switch]$SilentBackup
    )

    if (-not $SilentBackup -and $null -ne $BackupList) {
        $oldVal = Get-AndroidSettingValue -Namespace $Namespace -Key $Key
        $BackupList.Add([PSCustomObject]@{
            Namespace = $Namespace
            Key       = $Key
            OldValue  = $oldVal
            NewValue  = $Value
        })
    }

    $out = Invoke-Adb -Arguments @("shell", "settings", "put", $Namespace, $Key, $Value)
    $text = ($out -join " ").Trim()
    if (-not $text -and $script:LastAdbExitCode -eq 0) {
        Write-Host "  [OK] $Namespace/$Key = $Value" -ForegroundColor Green
        Write-Log "Ayar uygulandi: $Namespace/$Key = $Value"
    } else {
        Write-Host "  [UYARI] $Namespace/$Key -> $text" -ForegroundColor Yellow
        Write-Log "Ayar uyarisi ($Namespace/$Key): $text" "WARN"
    }
}

function Set-AnimationSettings {
    param([System.Collections.Generic.List[object]]$BackupList)
    Write-Host ""
    Write-Host "--- A) Animasyon & Akicilik Optimizasyonu (0.5x) ---" -ForegroundColor Cyan
    Set-AndroidSetting "global" "window_animation_scale" "0.5" $BackupList
    Set-AndroidSetting "global" "transition_animation_scale" "0.5" $BackupList
    Set-AndroidSetting "global" "animator_duration_scale" "0.5" $BackupList
}

function Set-BatteryPerformanceSettings {
    param([System.Collections.Generic.List[object]]$BackupList)
    Write-Host ""
    Write-Host "--- B) Pil, Doze & Arka Plan Optimizasyonu ---" -ForegroundColor Cyan

    $globalBattery = @(
        @("wifi_scan_always_enabled", "0"),
        @("ble_scan_always_enabled", "0"),
        @("wifi_power_save", "1"),
        @("network_recommendations_enabled", "0"),
        @("wifi_wakeup_enabled", "0"),
        @("app_standby_enabled", "1"),
        @("adaptive_battery_management_enabled", "1"),
        @("activity_starts_logging_enabled", "0")
    )
    foreach ($kv in $globalBattery) {
        Set-AndroidSetting "global" $kv[0] $kv[1] $BackupList
    }

    if ($script:DeviceInfo.SdkInt -eq 0 -or $script:DeviceInfo.SdkInt -ge 30) {
        Set-AndroidSetting "global" "cached_apps_freezer" "enabled" $BackupList
    }

    $mfr = ($script:DeviceInfo.Manufacturer + " " + $script:DeviceInfo.Brand).ToLower()
    if ($mfr -match "samsung") {
        Write-Host "  [Marka: Samsung ek pil ayarlari]" -ForegroundColor DarkCyan
        Set-AndroidSetting "system" "mcf_continuity" "0" $BackupList
        Set-AndroidSetting "system" "nearby_scanning_enabled" "0" $BackupList
        Set-AndroidSetting "system" "nearby_scanning_permission_allowed" "0" $BackupList
    }
}

function Set-PrivacyTelemetrySettings {
    param([System.Collections.Generic.List[object]]$BackupList)
    Write-Host ""
    Write-Host "--- C) Gizlilik & Telemetri Kapatma ---" -ForegroundColor Cyan

    $universalPrivacy = @(
        @("global", "send_action_app_error", "0"),
        @("secure", "send_action_app_error", "0"),
        @("global", "upload_apk_enable", "0"),
        @("secure", "limit_ad_tracking", "1"),
        @("secure", "usage_metrics_marketing_enabled", "0"),
        @("global", "sys_traced", "0"),
        @("global", "hotword_detection_enabled", "0"),
        @("secure", "assist_structure_enabled", "0"),
        @("secure", "assist_screenshot_enabled", "0"),
        @("global", "personalized_ad_enabled", "0"),
        @("secure", "anr_show_background", "0")
    )
    foreach ($item in $universalPrivacy) {
        Set-AndroidSetting $item[0] $item[1] $item[2] $BackupList
    }

    $mfr = ($script:DeviceInfo.Manufacturer + " " + $script:DeviceInfo.Brand).ToLower()
    if ($mfr -match "samsung") {
        Write-Host "  [Marka: Samsung gizlilik ayarlari]" -ForegroundColor DarkCyan
        Set-AndroidSetting "system" "samsung_errorlog_agree" "0" $BackupList
        Set-AndroidSetting "system" "send_security_reports" "0" $BackupList
        Set-AndroidSetting "system" "marketing_info_enabled" "0" $BackupList
        Set-AndroidSetting "secure" "samsung_customization_service_enabled" "0" $BackupList
    } elseif ($mfr -match "xiaomi|redmi|poco") {
        Write-Host "  [Marka: Xiaomi/Redmi/POCO gizlilik ayarlari]" -ForegroundColor DarkCyan
        Set-AndroidSetting "secure" "miui_report_usage" "0" $BackupList
        Set-AndroidSetting "secure" "upload_log_pref" "0" $BackupList
    } elseif ($mfr -match "oppo|realme|oneplus") {
        Write-Host "  [Marka: OPPO/Realme/OnePlus gizlilik ayarlari]" -ForegroundColor DarkCyan
        Set-AndroidSetting "system" "oplus_customize_experience_improvement" "0" $BackupList
        Set-AndroidSetting "secure" "user_experience_program" "0" $BackupList
        Set-AndroidSetting "system" "oem_join_user_plan_settings" "0" $BackupList
    } elseif ($mfr -match "huawei|honor") {
        Write-Host "  [Marka: Huawei/Honor gizlilik ayarlari]" -ForegroundColor DarkCyan
        Set-AndroidSetting "secure" "user_experience_involved" "0" $BackupList
        Set-AndroidSetting "secure" "hw_ue_plan" "0" $BackupList
    }
}

function Set-PrivateDnsConfig {
    param(
        [string]$Hostname,
        [string]$Mode = "hostname"
    )

    if (-not (Assert-DeviceConnected)) { return }

    if ($script:DeviceInfo.SdkInt -gt 0 -and $script:DeviceInfo.SdkInt -lt 28) {
        Write-Host "[UYARI] Private DNS Android 9.0 (SDK 28) ve uzeri gerektirir." -ForegroundColor Yellow
        return
    }

    $backupList = New-Object 'System.Collections.Generic.List[object]'
    if ($Mode -eq "hostname" -and $Hostname) {
        Set-AndroidSetting "global" "private_dns_mode" "hostname" $backupList
        Set-AndroidSetting "global" "private_dns_specifier" $Hostname $backupList
        Write-Host "[OK] Private DNS ayarlandi: $Hostname" -ForegroundColor Green
    } else {
        Set-AndroidSetting "global" "private_dns_mode" $Mode $backupList
        Write-Host "[OK] Private DNS modu ayarlandi: $Mode" -ForegroundColor Green
    }
    [void](Save-DeviceBackup -Reason "Private DNS ($Mode $Hostname)" -SettingRecords $backupList.ToArray())
}

function Invoke-PrivateDnsMenu {
    if (-not (Assert-DeviceConnected)) { return }

    $curMode = Get-AndroidSettingValue "global" "private_dns_mode"
    $curSpec = Get-AndroidSettingValue "global" "private_dns_specifier"

    Write-Host ""
    Write-Host "=== Private DNS Ayari (Secmeli / Opsiyonel) ===" -ForegroundColor Cyan
    Write-Host "  Mevcut Durum: Mod=$curMode | Sunucu=$curSpec" -ForegroundColor Gray
    Write-Host "  [1] AdGuard DNS (dns.adguard-dns.com - Reklam & Izleyici Engelleme)"
    Write-Host "  [2] AdGuard Aile (family.adguard-dns.com - Reklam + Yetiskin Filtre)"
    Write-Host "  [3] Cloudflare (one.one.one.one - Hizli & Gizlilik)"
    Write-Host "  [4] Quad9 (dns.quad9.net - Zararli Yazilim Engelleme)"
    Write-Host "  [5] NextDNS (Kendi ID'nizi girin)"
    Write-Host "  [6] Ozel DNS Sunucusu Gir"
    Write-Host "  [7] Otomatik (opportunistic)"
    Write-Host "  [8] Kapat (off)"
    Write-Host "  [0] Iptal"

    $sel = Read-Host "Seciminiz"
    switch ($sel) {
        "1" { Set-PrivateDnsConfig -Hostname "dns.adguard-dns.com" }
        "2" { Set-PrivateDnsConfig -Hostname "family.adguard-dns.com" }
        "3" { Set-PrivateDnsConfig -Hostname "one.one.one.one" }
        "4" { Set-PrivateDnsConfig -Hostname "dns.quad9.net" }
        "5" {
            $nid = Read-Host "NextDNS Profil ID (orn. a1b2c3)"
            if ($nid) { Set-PrivateDnsConfig -Hostname "$($nid.Trim()).dns.nextdns.io" }
        }
        "6" {
            $custom = Read-Host "DNS Hostname (orn. dns.mullvad.net)"
            if ($custom) { Set-PrivateDnsConfig -Hostname $custom.Trim() }
        }
        "7" { Set-PrivateDnsConfig -Mode "opportunistic" }
        "8" { Set-PrivateDnsConfig -Mode "off" }
        default { return }
    }
}

function Invoke-SystemOptimizations {
    param([switch]$RunAll)

    if (-not (Assert-DeviceConnected)) { return }

    if ($RunAll) {
        $backupList = New-Object 'System.Collections.Generic.List[object]'
        Set-AnimationSettings $backupList
        Set-BatteryPerformanceSettings $backupList
        Set-PrivacyTelemetrySettings $backupList
        [void](Save-DeviceBackup -Reason "Tum Sistem Optimizasyonlari" -SettingRecords $backupList.ToArray())
        return
    }

    while ($true) {
        Write-Host ""
        Write-Host "=== Sistem Ayar Optimizasyonlari ===" -ForegroundColor Cyan
        Write-Host "  [1] Animasyon & Akicilik (0.5x hiz)"
        Write-Host "  [2] Pil, Doze & Arka Plan Optimizasyonu"
        Write-Host "  [3] Gizlilik & Telemetri Kapatma"
        Write-Host "  [4] Private DNS Ayari (Secmeli: AdGuard / NextDNS / Cloudflare)"
        Write-Host "  [5] Temel Optimizasyonlarin Hepsini Uygula (1 + 2 + 3 - DNS haric)"
        Write-Host "  [0] Ana Menuye Don"
        $sub = Read-Host "Seciminiz"

        $backupList = New-Object 'System.Collections.Generic.List[object]'
        switch ($sub) {
            "1" {
                Set-AnimationSettings $backupList
                [void](Save-DeviceBackup -Reason "Animasyon Optimizasyonu" -SettingRecords $backupList.ToArray())
            }
            "2" {
                Set-BatteryPerformanceSettings $backupList
                [void](Save-DeviceBackup -Reason "Pil ve Doze Optimizasyonu" -SettingRecords $backupList.ToArray())
            }
            "3" {
                Set-PrivacyTelemetrySettings $backupList
                [void](Save-DeviceBackup -Reason "Gizlilik ve Telemetri Optimizasyonu" -SettingRecords $backupList.ToArray())
            }
            "4" {
                Invoke-PrivateDnsMenu
            }
            "5" {
                Set-AnimationSettings $backupList
                Set-BatteryPerformanceSettings $backupList
                Set-PrivacyTelemetrySettings $backupList
                [void](Save-DeviceBackup -Reason "Tum Sistem Optimizasyonlari" -SettingRecords $backupList.ToArray())
            }
            "0" { return }
            default { Write-Host "Gecersiz secim." -ForegroundColor Yellow }
        }
    }
}

function Reset-SystemOptimizations {
    if (-not (Assert-DeviceConnected)) { return }

    Write-Host ""
    Write-Host "Tum sistem ayarlari Android varsayilanlarina donduruluyor..." -ForegroundColor Yellow

    $defaults = @(
        @("global", "window_animation_scale", "1.0"),
        @("global", "transition_animation_scale", "1.0"),
        @("global", "animator_duration_scale", "1.0"),
        @("global", "cached_apps_freezer", "default"),
        @("global", "wifi_scan_always_enabled", "1"),
        @("global", "ble_scan_always_enabled", "1"),
        @("global", "wifi_power_save", "0"),
        @("global", "network_recommendations_enabled", "1"),
        @("global", "wifi_wakeup_enabled", "1"),
        @("global", "app_standby_enabled", "1"),
        @("global", "adaptive_battery_management_enabled", "1"),
        @("global", "activity_starts_logging_enabled", "1"),
        @("global", "send_action_app_error", "1"),
        @("secure", "send_action_app_error", "1"),
        @("global", "upload_apk_enable", "1"),
        @("secure", "limit_ad_tracking", "0"),
        @("secure", "usage_metrics_marketing_enabled", "1"),
        @("global", "sys_traced", "1"),
        @("global", "hotword_detection_enabled", "1"),
        @("secure", "assist_structure_enabled", "1"),
        @("secure", "assist_screenshot_enabled", "1"),
        @("global", "personalized_ad_enabled", "1"),
        @("secure", "anr_show_background", "0"),
        @("global", "private_dns_mode", "opportunistic")
    )
    foreach ($item in $defaults) {
        Set-AndroidSetting -Namespace $item[0] -Key $item[1] -Value $item[2] -SilentBackup
    }

    $mfr = ($script:DeviceInfo.Manufacturer + " " + $script:DeviceInfo.Brand).ToLower()
    if ($mfr -match "samsung") {
        foreach ($k in @("mcf_continuity", "nearby_scanning_enabled", "nearby_scanning_permission_allowed", "samsung_errorlog_agree", "send_security_reports", "marketing_info_enabled")) {
            Set-AndroidSetting -Namespace "system" -Key $k -Value "1" -SilentBackup
        }
        Set-AndroidSetting -Namespace "secure" -Key "samsung_customization_service_enabled" -Value "1" -SilentBackup
    } elseif ($mfr -match "xiaomi|redmi|poco") {
        Set-AndroidSetting -Namespace "secure" -Key "miui_report_usage" -Value "1" -SilentBackup
        Set-AndroidSetting -Namespace "secure" -Key "upload_log_pref" -Value "1" -SilentBackup
    } elseif ($mfr -match "oppo|realme|oneplus") {
        Set-AndroidSetting -Namespace "system" -Key "oplus_customize_experience_improvement" -Value "1" -SilentBackup
        Set-AndroidSetting -Namespace "secure" -Key "user_experience_program" -Value "1" -SilentBackup
        Set-AndroidSetting -Namespace "system" -Key "oem_join_user_plan_settings" -Value "1" -SilentBackup
    } elseif ($mfr -match "huawei|honor") {
        Set-AndroidSetting -Namespace "secure" -Key "user_experience_involved" -Value "1" -SilentBackup
        Set-AndroidSetting -Namespace "secure" -Key "hw_ue_plan" -Value "1" -SilentBackup
    }

    Write-Host "Varsayilan ayarlar geri yuklendi. (Tam orijinal degerler icin [R] Yedekten Geri Yukle kullanabilirsiniz.)" -ForegroundColor Green
}

# ------------------------------------------------------------------------------
# 8. Onbellek Temizligi & ART Derleme Optimizasyonu
# ------------------------------------------------------------------------------

function Invoke-Maintenance {
    if (-not (Assert-DeviceConnected)) { return }

    Write-Host ""
    Write-Host "=== Onbellek Temizligi & ART Optimizasyonu ===" -ForegroundColor Cyan
    $before = Get-DeviceMetrics
    Write-Host "1) Sistem geneli uygulama onbellekleri temizleniyor (pm trim-caches)..." -ForegroundColor White

    $trimOut = Invoke-Adb -Arguments @("shell", "pm", "trim-caches", "999G")
    if ($script:LastAdbExitCode -ne 0 -or ($trimOut -join " ") -match "Error|Exception|Invalid") {
        $trimOut = Invoke-Adb -Arguments @("shell", "pm", "trim-caches", "999999999999")
    }
    $trimText = ($trimOut -join " ").Trim()
    if ($trimText) {
        Write-Host "   Sonuc: $trimText" -ForegroundColor Gray
    } else {
        Write-Host "   [OK] Onbellek temizligi tamamlandi." -ForegroundColor Green
    }
    $after = Get-DeviceMetrics
    Write-Host "   Bos Alan: $($before.FreeSpace) -> $($after.FreeSpace)" -ForegroundColor DarkCyan

    Write-Host ""
    Write-Host "2) ART Derleme Optimizasyonu (bg-dexopt)" -ForegroundColor White
    Write-Host "   Not: Bu islem yuklu uygulama sayisina gore 1-3 dakika surebilir." -ForegroundColor Yellow
    $ans = Read-Host "ART derleme optimizasyonu calistirilsin mi? (E/H)"
    if ($ans -match "^[EeYy]$") {
        if ($script:DeviceInfo.SdkInt -gt 0 -and $script:DeviceInfo.SdkInt -lt 24) {
            Write-Host "   [UYARI] ART optimizasyonu Android 7.0 (SDK 24) ve uzeri gerektirir. Atlandi." -ForegroundColor Yellow
            return
        }
        Write-Host "   Calistiriliyor, lutfen USB baglantisini kesmeyin..." -ForegroundColor Cyan

        if ($script:DeviceInfo.SdkInt -ge 34) {
            $dexOut = Invoke-Adb -Arguments @("shell", "pm", "art", "dexopt-packages", "-r", "bg-dexopt")
            if ($script:LastAdbExitCode -ne 0 -or ($dexOut -join " ") -match "Unknown|Error") {
                $dexOut = Invoke-Adb -Arguments @("shell", "cmd", "package", "bg-dexopt-job")
            }
        } else {
            $dexOut = Invoke-Adb -Arguments @("shell", "cmd", "package", "bg-dexopt-job")
        }

        $dexText = ($dexOut -join " ").Trim()
        if ($dexText) {
            Write-Host "   Sonuc: $dexText" -ForegroundColor Green
        } else {
            Write-Host "   [OK] ART optimizasyonu tamamlandi." -ForegroundColor Green
        }
        Write-Log "ART optimizasyonu tamamlandi: $dexText"
    }
}

# ------------------------------------------------------------------------------
# 9. Ana Menu & Baslangic
# ------------------------------------------------------------------------------

function Show-Header {
    param([object[]]$Catalog)

    $t1 = 0; $t2 = 0; $t3 = 0
    foreach ($item in $Catalog) {
        if ($script:Whitelist.Contains($item.Pkg)) { continue }
        $isMatch = ($item.Action -eq "uninstall" -and $script:InstalledPackages.Contains($item.Pkg)) -or
                   ($item.Action -eq "disable" -and $script:EnabledPackages.Contains($item.Pkg))
        if (-not $isMatch) { continue }
        if ($item.Tier -le 1) { $t1++ }
        if ($item.Tier -le 2) { $t2++ }
        if ($item.Tier -le 3) { $t3++ }
    }

    $metrics = Get-DeviceMetrics

    Write-Host ""
    Write-Host "======================================================================" -ForegroundColor DarkCyan
    Write-Host "  ANDROID EVRENSEL DEBLOAT & OPTIMIZASYON ARACI v$($script:Version)" -ForegroundColor Cyan
    Write-Host "======================================================================" -ForegroundColor DarkCyan
    Write-Host ("  Cihaz   : {0} {1} ({2})" -f $script:DeviceInfo.Manufacturer, $script:DeviceInfo.Model, $script:DeviceInfo.Serial) -ForegroundColor White
    Write-Host ("  Sistem  : Android {0} (SDK {1}) | Paket: {2} | Pil: {3} | Bos: {4}" -f $script:DeviceInfo.Android, $script:DeviceInfo.Sdk, $script:InstalledPackages.Count, $metrics.Battery, $metrics.FreeSpace) -ForegroundColor Gray
    Write-Host ("  Eslesen : Seviye 1: {0} | Seviye 1+2: {1} | Seviye 1+2+3: {2} | Whitelist: {3}" -f $t1, $t2, $t3, $script:Whitelist.Count) -ForegroundColor Green
    Write-Host ("  VeriDir : {0}" -f $script:DataDir) -ForegroundColor DarkGray
    Write-Host "----------------------------------------------------------------------" -ForegroundColor DarkCyan
    Write-Host "  [1] Seviye 1 - Guvenli Temizlik ($t1 paket)"
    Write-Host "  [2] Seviye 2 - Dengeli Temizlik (Seviye 1 + 2: $t2 paket)"
    Write-Host "  [3] Seviye 3 - Agresif / Hard Temizlik (Drive, Auto vb. dahil: $t3 paket)"
    Write-Host "  [4] Sistem Ayar Optimizasyonlari (Animasyon / Pil / Gizlilik / DNS)"
    Write-Host "  [5] Tam Paket: Dengeli Temizlik + Sistem Optimizasyonlari (Onerilen)"
    Write-Host "  [6] Onizleme (Dry-Run) - Eslesen paketleri aciklamali listele"
    Write-Host "  [7] Onbellek Temizligi & ART Derleme Optimizasyonu"
    Write-Host "  [8] Sistem Ayarlarini Varsayilana Dondur"
    Write-Host "  [9] Cihaz Listesini Yenile / Kablosuz ADB Baglan"
    Write-Host "  [G] Gorsel Secim (Out-GridView) - Paketleri tek tek isaretle"
    Write-Host "  [M] Manuel Paket Yoneticisi & Whitelist (Ara/Kaldir/Haric Tut)"
    Write-Host "  [R] Yedekten Geri Yukle (Restore Paket + Ayarlar)"
    Write-Host "  [0] Cikis"
    Write-Host "======================================================================" -ForegroundColor DarkCyan
}

function Start-MainLoop {
    if (-not (Initialize-Workspace)) {
        Write-Host "[HATA] Veri klasoru (AndroidDebloatData) olusturulamadi!" -ForegroundColor Red
        return
    }

    Read-Whitelist

    $script:Adb = Find-AdbPath
    if (-not $script:Adb) {
        Write-Host "[HATA] adb.exe bulunamadi, internetten indirilemedi ve gomulu ADB cikartilamadi!" -ForegroundColor Red
        if (-not $NonInteractive) {
            Read-Host "Cikmak icin Enter tusuna basin"
        }
        return
    }

    Write-Host "ADB hazir: $($script:Adb) [$($script:AdbSource)]" -ForegroundColor DarkGray
    if (-not (Connect-Device -PreferredSerial $Serial)) {
        return
    }

    $catalog = Get-PackageCatalog

    # CLI / Non-Interactive Parametre Modu
    if ($RestoreBackup -or $Tier -gt 0 -or $DryRun -or $Optimize -or $PrivateDns) {
        if ($RestoreBackup) {
            Restore-DeviceBackup -BackupFilePath $RestoreBackup
        }
        if ($DryRun) {
            Show-DryRunPreview -Catalog $catalog
        } elseif ($Tier -gt 0) {
            Invoke-DebloatTier -Catalog $catalog -MaxTier $Tier -SkipConfirm:$NonInteractive
        }
        if ($Optimize) {
            Invoke-SystemOptimizations -RunAll
        }
        if ($PrivateDns) {
            if ($PrivateDns -in @("off", "opportunistic")) {
                Set-PrivateDnsConfig -Mode $PrivateDns
            } else {
                Set-PrivateDnsConfig -Hostname $PrivateDns
            }
        }
        if ($KillAdbOnExit) {
            [void](Invoke-Adb -Arguments @("kill-server") -NoDeviceSerial)
        }
        return
    }

    while ($true) {
        Show-Header -Catalog $catalog
        $choice = (Read-Host "Seciminiz").Trim().ToUpper()

        switch ($choice) {
            "1" {
                Invoke-DebloatTier -Catalog $catalog -MaxTier 1
            }
            "2" {
                Invoke-DebloatTier -Catalog $catalog -MaxTier 2
            }
            "3" {
                Invoke-DebloatTier -Catalog $catalog -MaxTier 3
            }
            "4" {
                Invoke-SystemOptimizations
            }
            "5" {
                Write-Host ""
                $ok5 = Read-Host "Tam Paket (Seviye 2 Dengeli Temizlik + Animasyon/Pil/Gizlilik) uygulansin mi? (E/H)"
                if ($ok5 -match "^[EeYy]$") {
                    Invoke-DebloatTier -Catalog $catalog -MaxTier 2 -SkipConfirm
                    Invoke-SystemOptimizations -RunAll
                    $dnsAns = Read-Host "Opsiyonel: Reklam engelleme icin Private DNS ayarlamak ister misiniz? (E/H)"
                    if ($dnsAns -match "^[EeYy]$") {
                        Invoke-PrivateDnsMenu
                    }
                    Write-Host ""
                    Write-Host "[TAMAMLANDI] Dengeli temizlik ve sistem optimizasyonlari uygulandi." -ForegroundColor Green
                }
            }
            "6" {
                Show-DryRunPreview -Catalog $catalog
            }
            "7" {
                Invoke-Maintenance
            }
            "8" {
                Reset-SystemOptimizations
            }
            "9" {
                $rMode = Read-Host "[U] USB Yenile | [W] Kablosuz ADB Baglan"
                if ($rMode -match "^[Ww]$") {
                    Connect-WirelessDevice
                }
                if (-not (Connect-Device)) {
                    return
                }
            }
            "G" {
                Invoke-InteractiveGridDebloat -Catalog $catalog
            }
            "M" {
                Invoke-ManualPackageManager
            }
            "R" {
                Restore-DeviceBackup
            }
            "0" {
                Write-Log "=== Oturum Sonlandi ==="
                if ($KillAdbOnExit) {
                    [void](Invoke-Adb -Arguments @("kill-server") -NoDeviceSerial)
                }
                Write-Host "Cikiliyor..." -ForegroundColor Gray
                return
            }
            default {
                Write-Host "Gecersiz secim. Menudeki seceneklerden birini girin." -ForegroundColor Yellow
            }
        }
    }
}

